contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test drives c.transfer and asserts that whenever the call does not revert, it returns true.
    function run(address contract_address, address[] memory tos, uint[] memory vs) public payable {
        // precondition: require address is not zero and not c itself (matches validAddress modifier),
        // and require tos and vs are non-empty and same length to reach the loop in transfer.
        require(contract_address != address(0x0) && contract_address != address(c));
        require(tos.length > 0 && vs.length > 0 && tos.length == vs.length);

        bool reverted;
        bool ret;
        // call transfer and catch revert
        try c.transfer(contract_address, tos, vs) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: if the call did not revert, it must have returned true.
        assert(reverted || ret == true);
    }

    receive() external payable {}
}

